export class BlobDecompressor {
  /**
   * Decompresses a zlib compressed blob.
   * Mostly used for XML-data compression, where dictionaries are used.
   * @param compressedBlob The blob with the compressed data
   * @param startoffset The startoffset where the zlib deflate should start. Some blobs have a 4 byte prefix for the dictionary version.
   * @returns The decompressed blob as string. If decompression failed, the string is empty
   */
  decompress(compressedBlob: Uint8Array, startoffset: number): string {
    const data = compressedBlob.subarray(startoffset);
    let dict: Uint8Array | undefined;
    // zlib header: CMF, FLG, [DICTID (adler32 of dictionary, big endian) if FLG.FDICT]
    if (data.length >= 6 && (data[1] & 0x20) !== 0) {
      const adler = ((data[2] << 24) | (data[3] << 16) | (data[4] << 8) | data[5]) >>> 0;
      dict = DICTIONARIES.get(adler);
      if (dict === undefined) {
        console.log(`BlobDecompressor: Have no dictionary for adler: 0x${adler.toString(16).toUpperCase()}`);
        return "";
      }
    }
    try {
      const out = dict ? inflateSync(data, { dictionary: dict }) : inflateSync(data);
      return new TextDecoder("utf-8").decode(out);
    } catch (e) {
      console.log(`BlobDecompressor: Blob decompression failed! ${(e as Error).message}`);
      return "";
    }
  }
}
